import { overdueInvoices, vatSummary } from '../src/reports.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const invoices = [
    { number: 'INV-001', customerId: 'C-001', status: 'issued', dueDate: '2026-10-15', lines: [], terms: 'NET30' },
    { number: 'INV-002', customerId: 'C-002', status: 'issued', dueDate: '2026-10-20', lines: [], terms: 'NET30' },
  ];
  const result = overdueInvoices(invoices, '2026-10-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices finds a single overdue issued invoice', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-05',
      lines: [{ sku: 'DEV-HOUR', qty: 10, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
      terms: 'NET30',
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-001');
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[0].dueDate, '2026-10-05');
  assert.equal(result[0].daysOverdue, 10);
  assert.equal(result[0].due, 114950);
});

